<?php declare(strict_types=1); require_once dirname(__DIR__,2).'/lib/tool-page.php'; $tool=['title'=>'Free JSON to CSV Converter','description'=>'Convert an array of JSON objects to CSV instantly.','url'=>'https://smarttoolz.in/tools/json-to-csv-converter/']; smarttoolz_tool_page_start($tool); ?><main class="tool-page"><section class="tool-intro"><h1>JSON to CSV Converter</h1><p>Convert JSON arrays into CSV text.</p></section><section class="tool-workspace"><div class="tool-panel"><textarea id="i" rows="12" placeholder='[{"name":"Alice","age":30}]'></textarea><button id="go" class="tool-btn">Convert to CSV</button><textarea id="o" rows="12" readonly></textarea></div></section></main><script>go.onclick=()=>{try{let a=JSON.parse(i.value);if(!Array.isArray(a)||!a.length)throw 0;let k=[...new Set(a.flatMap(x=>Object.keys(x)))];let q=v=>`"${String(v??'').replaceAll('"','""')}"`;o.value=[k.map(q).join(','),...a.map(x=>k.map(y=>q(x[y])).join(','))].join('\n')}catch(e){o.value='Invalid JSON array.'}}</script><?php smarttoolz_tool_page_end(); ?>